def multijoin_coindex(dimensions: Sequence[int]) -> int:
    if not dimensions or any(d < 0 for d in dimensions):
        raise ValueError("provide nonnegative dimensions for at least one factor")
    return sum(dimensions) + len(dimensions) - 1

