    examples = ([0], [0, 0, 0], [2, 0, 3, 1], [4, 4, 4])
    for ds in examples:
        print(list(ds), "->", multijoin_coindex(ds))

def self_join_certificate(a: int, p: int) -> int:
    if a < 0 or p < 1:
        raise ValueError("a must be nonnegative and p positive")
    return p * (a + 1) - 1

if __name__ == "__main__":
    for a in range(4):
        print(f"a={a}:", [self_join_certificate(a, p) for p in range(1, 7)])

