from typing import Sequence

def permutation_signature(dimensions: Sequence[int]) -> tuple[int, int, int]:
    if not dimensions or any(d < 0 for d in dimensions):
        raise ValueError("invalid dimensions")
    return (sum(dimensions), len(dimensions), sum(dimensions) + len(dimensions) - 1)

def same_join_coindex(left: Sequence[int], right: Sequence[int]) -> bool:
    return permutation_signature(left)[2] == permutation_signature(right)[2]

